import{_ as a,o as t,c as s,a6 as i}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse('{"title":"Database","description":"SQLite by default or PostgreSQL for a shared instance, how to switch between them, and where retention and backups are covered.","frontmatter":{"title":"Database","description":"SQLite by default or PostgreSQL for a shared instance, how to switch between them, and where retention and backups are covered.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/database.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/database.html"}],["meta",{"property":"og:title","content":"Database | Piwi for Playwright"}],["meta",{"property":"og:description","content":"SQLite by default or PostgreSQL for a shared instance, how to switch between them, and where retention and backups are covered."}]]},"headers":[],"relativePath":"operate/database.md","filePath":"operate/database.md","lastUpdated":1795158209000}'),n={name:"operate/database.md"};function o(r,e,h,d,l,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h1><p>Piwi stores runs, test cases, executions, clusters and settings in a relational database. Two backends are supported: <strong>SQLite</strong> (the default, zero configuration) and <strong>PostgreSQL</strong> (for multi-user or high-concurrency deployments). Both are exercised by the project&#39;s CI on every commit, and migrations run automatically on startup either way.</p><p>Test artifacts — HTML reports, traces, attachments — do <strong>not</strong> live here; they go to <a href="./storage.html">file storage</a>.</p><h2 id="sqlite-default" tabindex="-1">SQLite (default) <a class="header-anchor" href="#sqlite-default" aria-label="Permalink to &quot;SQLite (default)&quot;">​</a></h2><p>Nothing to configure. The database file is created at <code>.data/piwi.db</code> when the server starts, inside the directory you mounted as <code>/app/.data</code> (container) or the working directory you ran from (<code>npx</code>).</p><p>Set <code>PIWI_DATABASE_PATH</code> to put it somewhere else. Its directory must already exist — Piwi creates <code>.data/</code> itself only when <code>PIWI_DATABASE_PATH</code> is unset:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-OS7Rt" id="tab-ymzsO6S" checked><label data-title="Docker" for="tab-ymzsO6S">Docker</label><input type="radio" name="group-OS7Rt" id="tab-k4jALQL"><label data-title=".env" for="tab-k4jALQL">.env</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:3000:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.data:/app/.data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PIWI_DATABASE_PATH=/app/.data/custom.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenx/piwitests-server:latest</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_DATABASE_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/custom/path/database.db</span></span></code></pre></div></div></div><p>SQLite allows one writer at a time. Piwi queues its own writes, and waits up to 5 seconds for a lock held by another process (a script, a second server). That is ample for a team&#39;s test volume — a run submission is a short burst of writes — but if you see <code>database is locked</code> under load, move to PostgreSQL. Run one dashboard replica with either database: the SSE event bus is in-process (<a href="./deployment.html#resource-requirements">Deployment</a>).</p><h2 id="postgresql" tabindex="-1">PostgreSQL <a class="header-anchor" href="#postgresql" aria-label="Permalink to &quot;PostgreSQL&quot;">​</a></h2><p>Set <code>PIWI_DATABASE_URL</code> and Piwi uses PostgreSQL instead of SQLite, creating and migrating every table on startup. PostgreSQL <strong>14+</strong>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postgresql://user:password@localhost:5432/piwi_dashboard</span></span></code></pre></div><p><code>PIWI_DATABASE_PATH</code> is ignored while <code>PIWI_DATABASE_URL</code> is set. A ready-to-run Compose stack with a <code>postgres:17-alpine</code> service is in the <a href="./deployment.html#docker-compose-with-postgresql">deployment guide</a>.</p><p>To try it locally against a throwaway server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5432:5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_USER=postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_PASSWORD=postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_DB=piwi_dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres:17-alpine</span></span></code></pre></div><h3 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h3><p>An instance opens <strong>at most 10 connections</strong> to PostgreSQL, and only as its queries need them. Set <code>PIWI_DATABASE_POOL_MAX</code> to change that number, for instance below 10 on a server whose role is limited to fewer connections:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_DATABASE_POOL_MAX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">4</span></span></code></pre></div><p>A <code>max</code> in the connection string (<code>?max=4</code>), then postgres.js&#39;s own <code>PGMAX</code>, set it too; <code>PIWI_DATABASE_POOL_MAX</code> wins over both. A value that is not a whole number of at least 1 is left out, and one above 1,000 is lowered to 1,000, each with a warning in the server&#39;s log.</p><h3 id="jit-compilation" tabindex="-1">JIT compilation <a class="header-anchor" href="#jit-compilation" aria-label="Permalink to &quot;JIT compilation&quot;">​</a></h3><p>Each connection turns PostgreSQL&#39;s JIT compilation off (<code>jit=off</code>, sent as the connection opens). With it on, PostgreSQL compiles every query whose estimated cost passes <code>jit_above_cost</code>, at each run. The queries that read each test&#39;s latest results leave out the runs that never count toward its history (Flake Lab and probe runs, bisect steps, reproductions, private runs and incidents), and their estimate grows with the tests times those runs, which accumulate while retention is off: with 300 tests and 20,000 such runs, resolving a test selection takes 812 ms with JIT and 40 ms without.</p><p>A connection pooler may not pass the parameter on. PgBouncer refuses it unless <code>jit</code> is in its <code>ignore_startup_parameters</code>, and then drops it. When a connection with the parameter is refused and one without it is accepted, Piwi keeps the second and logs a warning. Either way JIT then follows the server&#39;s setting, which you can turn off for Piwi&#39;s database alone:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> piwi_dashboard </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="switching-backends" tabindex="-1">Switching backends <a class="header-anchor" href="#switching-backends" aria-label="Permalink to &quot;Switching backends&quot;">​</a></h2><p>There is <strong>no migration path between SQLite and PostgreSQL</strong> — pointing an instance at a new backend gives you an empty dashboard, not a converted one. Switch before you accumulate history you care about, or accept starting fresh. Your file storage is unaffected either way.</p><h2 id="retention-and-backups" tabindex="-1">Retention and backups <a class="header-anchor" href="#retention-and-backups" aria-label="Permalink to &quot;Retention and backups&quot;">​</a></h2><ul><li><strong>Retention</strong> — the nightly sweep prunes runs older than <code>PIWI_RETENTION_DAYS</code>, off by default. See <a href="./storage.html#data-retention">Data retention</a>.</li><li><strong>Backups</strong> — SQLite has an online-consistent backup recipe, PostgreSQL uses <code>pg_dump</code>. Both, plus what to copy alongside the database, are in <a href="./backup-restore.html">Backup &amp; restore</a>.</li><li><strong>Upgrades apply migrations automatically and they are forward-only.</strong> Read <a href="./upgrading.html">Upgrading</a> before bumping a version tag.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/reference/configuration.html#database">Configuration reference</a> — every <code>PIWI_DATABASE_*</code> and retention variable</li><li><a href="./storage.html">Storage &amp; retention</a> — where reports, traces and attachments go</li><li><a href="./deployment.html">Deployment</a> — Compose and Kubernetes, and <a href="./one-click-deploy.html">one-click deploy</a> templates</li><li>Changing the schema is a contributor task, not an operator one: <a href="https://github.com/PiwiTests/piwi/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a></li></ul>',28)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
